// Read-only probe script: launches headless Chromium (fake media device, no real
// hardware/network touched) and reports facts about browser API behavior.
// Nothing here writes, deletes, publishes, or notifies anything external.
import { chromium } from 'playwright-core';

const results = {};

const browser = await chromium.launch({
  executablePath: '/opt/pw-browsers/chromium/chrome-linux/chrome',
  args: [
    '--use-fake-device-for-media-stream',
    '--use-fake-ui-for-media-stream', // auto-accept the permission prompt, no real mic touched
  ],
});
const context = await browser.newContext();
await context.grantPermissions(['microphone']);
const page = await context.newPage();
await page.goto('about:blank');

results.chromeVersion = await browser.version();

// --- Claim: synthetic KeyboardEvent leaves keyCode/which/charCode at 0 unless
// explicitly set in the init dict (deprecated fields are NOT auto-derived from `key`).
results.keyboardEventDefaults = await page.evaluate(() => {
  const bare = new KeyboardEvent('keydown', { key: 'A' });
  const explicit = new KeyboardEvent('keydown', { key: 'A', keyCode: 65, which: 65 });
  return {
    bareKeyCode: bare.keyCode,
    bareWhich: bare.which,
    explicitKeyCode: explicit.keyCode,
    explicitWhich: explicit.which,
  };
});

// --- Claim: constructed input events (Keyboard/Mouse) default to bubbles:false,
// cancelable:false, composed:false unless the init dict says otherwise.
results.eventInitDefaults = await page.evaluate(() => {
  const kb = new KeyboardEvent('keydown', { key: 'A' });
  const mouse = new MouseEvent('click');
  const custom = new CustomEvent('cc:speak');
  return {
    keyboard: { bubbles: kb.bubbles, cancelable: kb.cancelable, composed: kb.composed },
    mouse: { bubbles: mouse.bubbles, cancelable: mouse.cancelable, composed: mouse.composed },
    custom: { bubbles: custom.bubbles, cancelable: custom.cancelable, composed: custom.composed },
  };
});

// --- Claim: suppressLocalAudioPlayback / restrictOwnAudio are getDisplayMedia-only
// constraints and getUserMedia ignores them silently (no throw, no OverconstrainedError).
results.getUserMediaIgnoresScreenCaptureConstraints = await page.evaluate(async () => {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        suppressLocalAudioPlayback: true,
        restrictOwnAudio: true,
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      },
    });
    const track = stream.getAudioTracks()[0];
    const settings = track.getSettings();
    const constraints = track.getConstraints();
    stream.getTracks().forEach((t) => t.stop());
    return { threw: false, settings, constraints };
  } catch (e) {
    return { threw: true, name: e.name, message: e.message };
  }
});

// --- Claim: getSupportedConstraints() surface — do echoCancellation etc. appear,
// and do suppressLocalAudioPlayback/restrictOwnAudio appear (they shouldn't, since
// they belong to a different, display-capture-only constraint set).
results.supportedConstraints = await page.evaluate(() => {
  const sc = navigator.mediaDevices.getSupportedConstraints();
  return {
    echoCancellation: !!sc.echoCancellation,
    noiseSuppression: !!sc.noiseSuppression,
    autoGainControl: !!sc.autoGainControl,
    suppressLocalAudioPlayback: !!sc.suppressLocalAudioPlayback,
    restrictOwnAudio: !!sc.restrictOwnAudio,
  };
});

// --- Claim: webkitSpeechRecognition exposes no way to pass MediaTrackConstraints
// (no constructor param, no method) — feature-detect the whole prototype surface.
results.speechRecognitionSurface = await page.evaluate(() => {
  const Ctor = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!Ctor) return { exists: false };
  const rec = new Ctor();
  const protoProps = new Set();
  let proto = Object.getPrototypeOf(rec);
  while (proto && proto !== Object.prototype) {
    Object.getOwnPropertyNames(proto).forEach((p) => protoProps.add(p));
    proto = Object.getPrototypeOf(proto);
  }
  const instanceProps = Object.getOwnPropertyNames(rec);
  return {
    exists: true,
    ctorLength: Ctor.length, // arity of the constructor — 0 means no constraints param accepted
    protoProps: [...protoProps].sort(),
    instanceProps: instanceProps.sort(),
    hasProcessLocally: 'processLocally' in rec,
    hasPhrasesProp: 'phrases' in rec,
    hasStaticAvailable: typeof Ctor.available === 'function',
  };
});

// --- Claim: SpeechRecognitionPhrase exists as a global (on-device biasing surface).
results.speechRecognitionPhraseGlobal = await page.evaluate(() => ({
  exists: typeof window.SpeechRecognitionPhrase !== 'undefined',
}));

// --- Claim: speechSynthesis.getVoices() is synchronous & can return empty
// immediately after page load, with a 'voiceschanged' event firing later —
// i.e. the API is architecturally lazy/async by design (feature-detect only;
// headless has no TTS backend so we can't observe a real voice list appear).
results.speechSynthesisLazyVoices = await page.evaluate(() => {
  const immediate = speechSynthesis.getVoices();
  return {
    immediateLength: immediate.length,
    isArray: Array.isArray(immediate),
    hasVoicesChangedEvent: 'onvoiceschanged' in speechSynthesis,
  };
});

// --- Claim (chrome-extension architecture, cross-check only): chrome.* is not
// present at all on a plain page (sanity check the namespace is extension-gated,
// not a general web API) — full "content script vs background" split needs a
// loaded extension; see note in PR body about what remains unprobed.
results.chromeNamespaceOnPlainPage = await page.evaluate(() => ({
  hasChrome: typeof window.chrome !== 'undefined',
  hasChromeTts: typeof window.chrome?.tts !== 'undefined',
}));

await browser.close();

console.log(JSON.stringify(results, null, 2));

