  return {
    keyboard: { bubbles: kb.bubbles, cancelable: kb.cancelable, composed: kb.composed },
    mouse: { bubbles: mouse.bubbles, cancelable: mouse.cancelable, composed: mouse.composed },
    custom: { bubbles: custom.bubbles, cancelable: custom.cancelable, composed: custom.composed },
  };
