  res.writeHead(200, { 'content-type': 'text/html' });
  res.end('<!doctype html><title>probe</title><body>probe page</body>');
});
await new Promise((resolve) => server.listen(0, '[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]', resolve));
const { port } = server.address();

