  bgResult = await workers[0].evaluate(() => globalThis.__probeResult ?? null);
} else {
  // Service worker may need a beat to spin up; poll briefly.
  for (let i = 0; i < 10 && !bgResult; i++) {
    await new Promise((r) => setTimeout(r, 300));
    const ws = context.serviceWorkers();
    if (ws.length) bgResult = await ws[0].evaluate(() => globalThis.__probeResult ?? null);
  }
}

